package de.kopfzentrum.gam.waitingroom;
import de.kopfzentrum.gam.auth.AuthenticatedUser;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/waiting-room") public class WaitingRoomVisitController{private final WaitingRoomVisitRepository r;public WaitingRoomVisitController(WaitingRoomVisitRepository r){this.r=r;}@GetMapping public List<WaitingRoomVisit> list(@RequestParam(required=false)String q,@RequestParam(required=false)String status){return r.list(q,status);}@PostMapping public WaitingRoomVisit create(@RequestBody WaitingRoomVisitRequest v,@AuthenticationPrincipal AuthenticatedUser u){return r.create(v,u==null?"system":u.getUsername());}@PostMapping("/{id}/transition") public WaitingRoomVisit transition(@PathVariable long id,@RequestBody Map<String,String> p,@AuthenticationPrincipal AuthenticatedUser u){return r.transition(id,p.get("status"),p.get("room"),p.get("practitioner"),p.get("nextStep"),p.get("note"),u==null?"system":u.getUsername());}@DeleteMapping("/{id}") public void delete(@PathVariable long id){r.delete(id);}}
